"""Extract a perspective from a new panorama plus its selected cardinal rear repair."""
from pathlib import Path
import argparse,json,math
import numpy as np
from stack_math import rays,sample,sha,load,save
p=argparse.ArgumentParser();p.add_argument('--input',type=Path,required=True);p.add_argument('--rear',type=Path,required=True);p.add_argument('--output',type=Path,required=True);p.add_argument('--yaw',type=float,default=0);p.add_argument('--pitch',type=float,default=-90);p.add_argument('--fov',type=float,default=110);p.add_argument('--size',type=int,default=1400);a=p.parse_args();images={'base':load(a.input)[...,:3],'rear':load(a.rear)[...,:3]};assert images['base'].shape[1]==2*images['base'].shape[0]
config={'fovDegrees':110,'frontMask':[0,0,1,1]};w=rays(a.size,math.radians(a.yaw),math.radians(a.pitch),a.fov);values,_=sample(images,config,w,['rear']);result=np.rint(np.clip(values,0,255)).astype(np.uint8);save(a.output,result)
record={'schemaVersion':1,'operation':'deterministic current candidate base+selected rear repair perspective','inputs':{'base':{'path':str(a.input),'sha256':sha(a.input)},'rear':{'path':str(a.rear),'sha256':sha(a.rear)}},'output':{'path':str(a.output),'sha256':sha(a.output),'size':[a.size,a.size]},'camera':{'yawDegrees':a.yaw,'pitchDegrees':a.pitch,'horizontalFovDegrees':a.fov,'verticalFovDegrees':a.fov},'rearPatch':{'yawDegrees':180,'pitchDegrees':0,'fovDegrees':110,'edgeFull':.70,'edgeZero':.96,'blend':'Same existing normalized runtime repair blend'},'scriptSha256':sha(__file__),'stackMathSha256':sha(Path(__file__).with_name('stack_math.py')),'noArtisticEditing':True,'orientation':'Cardinaldown yaw0/pitch-90: image right+X,up+Y,view-Z. Includes repaired rear in overlap; original inputs unchanged.'};a.output.with_suffix('.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps(record['output']))
